"""Permutation ranking / unranking via factoradic Lehmer codes."""
from __future__ import annotations
from math import factorial

def extract_factoradic(rank: int, n: int) -> list[int]:
    q, out = rank, []
    for i in range(n):
        out.append(q % (i + 1)); q //= (i + 1)
    return out  # low->high, digit i in [0, i]

def unrank(rank: int, n: int) -> list[int]:
    code = list(reversed(extract_factoradic(rank, n)))  # code[j] in [0, n-1-j]
    pool = list(range(n)); perm = []
    for c in code:
        perm.append(pool.pop(c))
    return perm

def rank_of(perm: list[int]) -> int:
    n = len(perm); pool = list(range(n)); code = []
    for x in perm:
        idx = pool.index(x); code.append(idx); pool.pop(idx)
    r, f = 0, 1
    for j in range(n):
        r += list(reversed(code))[j] * f
        f *= (j + 1)
    return r

if __name__ == "__main__":
    n = 4
    for r in range(factorial(n)):
        assert rank_of(unrank(r, n)) == r
    for r in [0, 12, 23]:
        print(f"rank {r:2d} <-> {unrank(r, n)}")
    print("Ranking is a verified bijection [0, n!) <-> S_n.")

"""Base-independent odometer: successor by carry propagation matches value+1."""
from __future__ import annotations
from math import prod
from typing import Callable

def radix_prod(bases: Callable[[int], int], k: int) -> int:
    return prod(bases(i) for i in range(k))

def value(bases: Callable[[int], int], digits: list[int]) -> int:
    total, running = 0, 1
    for i, c in enumerate(digits):
        total += c * running; running *= bases(i)
    return total

def successor(bases: Callable[[int], int], digits: list[int]) -> list[int]:
    out = digits[:]; i, carry = 0, 1
    while carry and i < len(out):
        out[i] += carry
        if out[i] >= bases(i):
            out[i] = 0; carry = 1
        else:
            carry = 0
        i += 1
    return out

def check(bases: Callable[[int], int], k: int) -> None:
    Pk = radix_prod(bases, k)
    d = [0] * k
    for n in range(Pk - 1):
        d = successor(bases, d)
        assert value(bases, d) == n + 1

if __name__ == "__main__":
    check(lambda i: i + 1, 5)   # factorial system
    check(lambda i: 2, 6)       # binary
    check(lambda i: i + 2, 4)   # mixed bases
    print("Carry propagation yields value+1 in every system (base-independent).")
